 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find complete rectangular outlines, then identify remaining point colors.
    frames = []
    frame_cells = set()
    for color in range(1, 10):
        cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        if not cells:
            continue
        # A frame is a connected rectangular perimeter; test bounding boxes of
        # same-color connected components, so unrelated point colors are ignored.
        unseen = set(cells)
        while unseen:
            seed = unseen.pop()
            comp = {seed}
            stack = [seed]
            while stack:
                r, c = stack.pop()
                for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if p in unseen:
                        unseen.remove(p); comp.add(p); stack.append(p)
            rs = [p[0] for p in comp]; cs = [p[1] for p in comp]
            r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                         if r in (r0,r1) or c in (c0,c1)}
            if comp == perimeter:
                frames.append((color,r0,r1,c0,c1))
                frame_cells |= perimeter
    markers = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r,c) not in frame_cells:
                markers[color] = markers.get(color, 0) + 1
    out = [[0]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in frames:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    out[r][c] = color
        ih, iw = r1-r0-1, c1-c0-1
        # Each marker color encodes the checkerboard to place in a frame;
        # its point count equals the number of painted checker cells.
        for marker, count in markers.items():
            for parity in (0,1):
                spots = [(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)
                         if ((r-r0-1)+(c-c0-1)) % 2 == parity]
                if len(spots) == count:
                    for r,c in spots: out[r][c] = marker
                    break
